//! Telling generated files apart, so the viewer can collapse them as GitHub does.
use std::collections::HashMap;
use std::sync::{LazyLock, Mutex};

use regex::{Regex, RegexSet};

use crate::concurrency::map_limit;
use crate::git::{GitRepo, WORKTREE};
use crate::protocol::{ChangeStatus, ChangedFile};

/// How much of a file the content sniff reads. Markers past this are missed; globs remain the escape hatch.
pub const SNIFF_BYTES: usize = 4096;

/// Path shapes that are generated by convention, independent of content.
static PATH_PATTERNS: LazyLock<RegexSet> = LazyLock::new(|| {
    RegexSet::new([
        r"(^|/)(package-lock\.json|pnpm-lock\.yaml|yarn\.lock|uv\.lock|Cargo\.lock|poetry\.lock|composer\.lock|Gemfile\.lock|go\.sum|flake\.lock)$",
        r"\.lock$",
        r"\.min\.(js|css|mjs)$",
        r"\.(js|mjs|cjs|css)\.map$",
        r"(^|/)__snapshots__/",
        r"\.snap$",
        r"_pb2(_grpc)?\.pyi?$",
        r"\.pb\.(go|cc|h|swift|rb|dart)$",
        r"\.(g|freezed|gr)\.dart$",
        r"\.generated\.[^/]+$",
        r"(^|/)(generated|__generated__|_generated)/",
        r"(^|/)(dist|build)/[^/]+\.(js|css)$",
    ])
    .unwrap()
});

/// Marker phrases the common code generators put in a file header.
static CONTENT_MARKERS: LazyLock<RegexSet> = LazyLock::new(|| {
    RegexSet::new([
        r"@generated\b",
        r"\bDO NOT EDIT\b",
        r"\bCode generated by\b",
        r"\b[Aa]uto-?generated\b",
        r"(?i)\bautomatically generated\b",
    ])
    .unwrap()
});

/// Generators write their marker in a comment; prose or code that mentions one does not count.
static COMMENT_LINE: LazyLock<Regex> =
    LazyLock::new(|| Regex::new(r#"(?i)^\s*(#|//|/\*|\*|--|<!--|;|"""|'''|=begin|%|REM\b|@rem\b)"#).unwrap());

/// True when `path` matches a generated-file convention or the first bytes carry a generator
/// marker. Binary content never counts as generated here.
pub fn looks_generated(path: &str, head: Option<&[u8]>) -> bool {
    if PATH_PATTERNS.is_match(path) {
        return true;
    }
    let Some(head) = head.filter(|h| !h.is_empty()) else {
        return false;
    };
    let head = &head[..head.len().min(SNIFF_BYTES)];
    if head.contains(&0) {
        return false;
    }
    String::from_utf8_lossy(head).split('\n').any(|line| COMMENT_LINE.is_match(line) && CONTENT_MARKERS.is_match(line))
}

/// The gitattribute GitHub reads to collapse generated files; `=false` opts a file out of the heuristics.
const GENERATED_ATTR: &str = "linguist-generated";
/// Concurrent worktree reads while flagging generated files.
const SNIFF_CONCURRENCY: usize = 8;
/// Sniff verdicts remembered by blob sha; the map is emptied, not evicted, past this.
const SNIFF_CACHE_MAX: usize = 20_000;

/// Flags a snapshot's generated files, remembering each blob's sniff verdict: a blob is immutable,
/// so a refresh reads only new content.
#[derive(Default)]
pub struct GeneratedFlags {
    sniffed: Mutex<HashMap<String, bool>>,
}

impl GeneratedFlags {
    /// Sets `generated` on each non-binary changed file. A `linguist-generated` gitattribute on the
    /// new side decides outright, as on GitHub; otherwise a path convention, then a content sniff.
    /// Never fails the snapshot: a failed lookup or read means the next heuristic, then false.
    pub async fn fill(&self, repo: &GitRepo, files: &mut [ChangedFile], new_sha: &str) {
        let textual: Vec<usize> = (0..files.len())
            .filter(|&i| files[i].status != ChangeStatus::D && !files[i].binary && files[i].submodule != Some(true))
            .collect();
        let paths: Vec<String> = textual.iter().map(|&i| files[i].path.clone()).collect();
        let marked = repo.attr(GENERATED_ATTR, &paths, new_sha).await.unwrap_or_default();
        let mut unknown = Vec::new();
        {
            let sniffed = self.sniffed.lock().unwrap();
            for i in textual {
                let f = &mut files[i];
                if let Some(&attr) = marked.get(&f.path) {
                    f.generated = attr;
                } else if looks_generated(&f.path, None) {
                    f.generated = true;
                } else if let Some(&known) = sniffed.get(&f.blob).filter(|_| !f.blob.is_empty()) {
                    f.generated = known;
                } else {
                    unknown.push(i);
                }
            }
        }
        let heads: Vec<Option<Vec<u8>>> = if new_sha == WORKTREE {
            map_limit(unknown.clone(), SNIFF_CONCURRENCY, |i| {
                let path = files[i].path.clone();
                async move { repo.head(WORKTREE, &path, SNIFF_BYTES).await.ok().flatten() }
            })
            .await
        } else {
            // A missing blob (the sniff cannot fail the snapshot) reads as not generated.
            let shas: Vec<String> = unknown.iter().map(|&i| files[i].blob.clone()).filter(|b| !b.is_empty()).collect();
            let found = repo.blob_heads(&shas, SNIFF_BYTES).await.unwrap_or_default();
            unknown.iter().map(|&i| found.get(&files[i].blob).cloned()).collect()
        };
        let mut sniffed = self.sniffed.lock().unwrap();
        for (i, head) in unknown.into_iter().zip(heads) {
            let f = &mut files[i];
            f.generated = looks_generated(&f.path, head.as_deref());
            if head.is_some() && !f.blob.is_empty() {
                if sniffed.len() >= SNIFF_CACHE_MAX {
                    sniffed.clear();
                }
                sniffed.insert(f.blob.clone(), f.generated);
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn matches_lockfiles_bundles_protobuf_output_and_generated_directories_by_path_alone() {
        let generated = [
            "package-lock.json",
            "sub/yarn.lock",
            "Cargo.lock",
            "app.min.js",
            "x/app.min.css",
            "a.js.map",
            "proto/x_pb2.py",
            "x.pb.go",
            "src/__snapshots__/a.snap",
            "generated/schema.ts",
            "lib/api.generated.ts",
            "dist/app.js",
        ];
        for path in generated {
            assert!(looks_generated(path, None), "{path}");
        }
        for path in
            ["src/main.py", "lock.py", "minified.md", "generate.py", "src/generated_at.py", "src/dist/nested/app.js"]
        {
            assert!(!looks_generated(path, Some(b"plain\n")), "{path}");
        }
    }

    #[test]
    fn sniffs_the_header_for_generator_markers_and_never_flags_binary_content() {
        let sniff = |path: &str, head: &[u8]| looks_generated(path, Some(head));
        assert!(sniff("a.py", b"# @generated by protoc\n"));
        assert!(sniff("a.go", b"// Code generated by mockery. DO NOT EDIT.\n"));
        assert!(sniff("a.ts", b"/* eslint-disable */\n// This file was automatically generated.\n"));
        assert!(!sniff("a.py", b"def generated_at():\n    pass\n"));
        // Mentions outside a comment: prose, or code that handles the markers.
        assert!(!sniff("README.md", b"Files with `@generated` or `DO NOT EDIT` headers start collapsed.\n"));
        assert!(!sniff("gen.ts", b"const MARKERS = [/@generated/, /DO NOT EDIT/];\n"));
        assert!(sniff("a.html", b"<!doctype html>\n<!-- @generated by docs-build -->\n"));
        assert!(!looks_generated("a.py", None));
        assert!(!sniff("a.py", b""));
        assert!(!sniff("a.bin", b"@generated\0\x01\x02"));
        // Only the first SNIFF_BYTES count.
        assert!(!sniff("a.py", format!("{}\n# @generated\n", "x".repeat(SNIFF_BYTES)).as_bytes()));
    }
}
